with seed(standard_code,code,name,seq,required,classification,grade_group) as (values
('พ 1.1','HPE-M2-01','อธิบายการเปลี่ยนแปลงด้านร่างกาย จิตใจ อารมณ์ สังคม และสติปัญญาในวัยรุ่น',1,true,'must_know','M2'),
('พ 1.1','HPE-M2-02','ระบุปัจจัยที่มีผลกระทบต่อการเจริญเติบโตและพัฒนาการด้านร่างกาย จิตใจ อารมณ์ สังคม และสติปัญญาในวัยรุ่น',2,true,'must_know','M2'),
('พ 2.1','HPE-M2-03','วิเคราะห์ปัจจัยที่มีอิทธิพลต่อเจตคติในเรื่องเพศ',3,true,'must_know','M2'),
('พ 2.1','HPE-M2-04','วิเคราะห์ปัญหาและผลกระทบที่เกิดจากการมีเพศสัมพันธ์ในวัยเรียน',4,true,'must_know','M2'),
('พ 2.1','HPE-M2-05','อธิบายวิธีป้องกันตนเองและหลีกเลี่ยงจากโรคติดต่อทางเพศสัมพันธ์ เอดส์ และการตั้งครรภ์โดยไม่พึงประสงค์',5,true,'must_know','M2'),
('พ 2.1','HPE-M2-06','อธิบายความสำคัญของความเสมอภาคทางเพศและวางตัวได้อย่างเหมาะสม',6,true,'must_know','M2'),
('พ 3.1','HPE-M2-07','นำผลการปฏิบัติตนเกี่ยวกับทักษะกลไกและทักษะการเคลื่อนไหวในการเล่นกีฬาจากแหล่งข้อมูลที่หลากหลายมาสรุปเป็นวิธีที่เหมาะสมในบริบทของตนเอง',7,true,'must_know','M2'),
('พ 3.1','HPE-M2-08','เล่นกีฬาไทยและกีฬาสากล ทั้งประเภทบุคคลและทีมอย่างละ ๑ ชนิด',8,true,'must_know','M2'),
('พ 3.1','HPE-M2-09','เปรียบเทียบประสิทธิภาพของรูปแบบการเคลื่อนไหวที่ส่งผลต่อการเล่นกีฬาและกิจกรรมในชีวิตประจำวัน',9,false,'should_know','M2'),
('พ 3.1','HPE-M2-10','ร่วมกิจกรรมนันทนาการ อย่างน้อย ๑ กิจกรรม และนำความรู้และหลักการที่ได้ไปปรับใช้ในชีวิตประจำวันอย่างเป็นระบบ',10,false,'should_know','M2'),
('พ 3.2','HPE-M2-11','อธิบายสาเหตุการเปลี่ยนแปลงทางกาย จิตใจ อารมณ์ สังคม และสติปัญญา ที่เกิดจากการออกกำลังกายและเล่นกีฬาเป็นประจำจนเป็นวิถีชีวิต',11,true,'must_know','M2'),
('พ 3.2','HPE-M2-12','เลือกเข้าร่วมกิจกรรมการออกกำลังกาย เล่นกีฬาตามความถนัดและความสนใจ พร้อมทั้งวิเคราะห์ความแตกต่างระหว่างบุคคลเพื่อเป็นแนวทางในการพัฒนาตนเอง',12,true,'must_know','M2'),
('พ 3.2','HPE-M2-13','มีวินัย ปฏิบัติตามกฎ กติกา และข้อตกลงในการเล่นกีฬาที่เลือก',13,false,'should_know','M2'),
('พ 3.2','HPE-M2-14','วางแผนการรุกและการป้องกันในการเล่นกีฬาที่เลือกและนำไปใช้ในการเล่นอย่างเหมาะสมกับทีม',14,true,'must_know','M2'),
('พ 3.2','HPE-M2-15','นำผลการปฏิบัติในการเล่นกีฬามาสรุปเป็นวิธีที่เหมาะสมกับตนเองด้วยความมุ่งมั่น',15,false,'should_know','M2'),
('พ 1.1','HPE-M46-01','อธิบายกระบวนการสร้างเสริมและดำรงประสิทธิภาพการทำงานของระบบอวัยวะต่าง ๆ',1,true,'must_know','M46'),
('พ 1.1','HPE-M46-02','วางแผนดูแลสุขภาพตามภาวะการเจริญเติบโตและพัฒนาการของตนเองและบุคคลในครอบครัว',2,true,'must_know','M46'),
('พ 2.1','HPE-M46-03','วิเคราะห์อิทธิพลของครอบครัว เพื่อน สังคม และวัฒนธรรมที่มีผลต่อพฤติกรรมทางเพศและการดำเนินชีวิต',3,true,'must_know','M46'),
('พ 2.1','HPE-M46-04','วิเคราะห์ค่านิยมในเรื่องเพศตามวัฒนธรรมไทยและวัฒนธรรมอื่น ๆ',4,false,'should_know','M46'),
('พ 2.1','HPE-M46-05','เลือกใช้ทักษะที่เหมาะสมในการป้องกัน ลดความขัดแย้ง และแก้ปัญหาเรื่องเพศและครอบครัว',5,true,'must_know','M46'),
('พ 2.1','HPE-M46-06','วิเคราะห์สาเหตุและผลของความขัดแย้งที่อาจเกิดขึ้นระหว่างนักเรียนหรือเยาวชนในชุมชน และเสนอแนวทางแก้ไขปัญหา',6,true,'must_know','M46'),
('พ 3.1','HPE-M46-07','วิเคราะห์ความคิดรวบยอดเกี่ยวกับการเคลื่อนไหวรูปแบบต่าง ๆ ในการเล่นกีฬา',7,true,'must_know','M46'),
('พ 3.1','HPE-M46-08','ใช้ความสามารถของตน เพื่อเพิ่มศักยภาพของทีม คำนึงถึงผลที่เกิดต่อผู้อื่นและสังคม',8,false,'should_know','M46'),
('พ 3.1','HPE-M46-09','เล่นกีฬาไทย กีฬาสากล ประเภทบุคคล/คู่ กีฬาประเภททีมอย่างน้อย ๑ ชนิด',9,true,'must_know','M46'),
('พ 3.1','HPE-M46-10','แสดงการเคลื่อนไหวได้อย่างสร้างสรรค์',10,false,'should_know','M46'),
('พ 3.1','HPE-M46-11','เข้าร่วมกิจกรรมนันทนาการนอกโรงเรียน และนำหลักการแนวคิดไปปรับปรุงและพัฒนาคุณภาพชีวิตของตนและสังคม',11,false,'should_know','M46'),
('พ 3.2','HPE-M46-12','ออกกำลังกายและเล่นกีฬาที่เหมาะสมกับตนเองอย่างสม่ำเสมอ และใช้ความสามารถของตนเองเพิ่มศักยภาพของทีม ลดความเป็นตัวตน คำนึงถึงผลที่เกิดต่อสังคม',12,false,'should_know','M46'),
('พ 4.1','HPE-M46-21','มีส่วนร่วมในการส่งเสริมและพัฒนาสุขภาพของบุคคลในชุมชน',21,false,'should_know','M46'),
('พ 4.1','HPE-M46-22','มีส่วนร่วมในการป้องกันความเสี่ยงต่อการใช้ยา การใช้สารเสพติดและความรุนแรง เพื่อสุขภาพของตนเอง ครอบครัว และสังคม',22,false,'should_know','M46'),
('พ 4.1','HPE-M46-24','วิเคราะห์ผลกระทบที่เกิดจากการครอบครอง การใช้และการจำหน่ายสารเสพติด',24,true,'must_know','M46'),
('พ 4.1','HPE-M46-26','วางแผน กำหนดแนวทางลดอุบัติเหตุ และสร้างเสริมความปลอดภัยในชุมชน',26,false,'should_know','M46'),
('พ 4.1','HPE-M46-27','มีส่วนร่วมในการสร้างเสริมความปลอดภัยในชุมชน',27,false,'should_know','M46'),
('พ 4.1','HPE-M46-28','ใช้ทักษะการตัดสินใจแก้ปัญหาในสถานการณ์ที่เสี่ยงต่อสุขภาพและความรุนแรง',28,false,'should_know','M46'),
('พ 4.1','HPE-M46-29','แสดงวิธีการช่วยฟื้นคืนชีพอย่างถูกวิธี',29,false,'should_know','M46')
)
insert into public.learning_objectives(topic_id,code,name,description,sequence_no,status)
select t.id,s.code,s.name,null,s.seq,'active' from seed s join public.learning_subjects sub on sub.code='HEALTH-PE' join public.learning_skills sk on sk.subject_id=sub.id and sk.code='HEALTH-PE' join public.learning_topics t on t.skill_id=sk.id and t.code=s.standard_code
on conflict(topic_id,code) do update set name=excluded.name,sequence_no=excluded.sequence_no,updated_at=now();
